import axios from 'axios';
//import { useDispatch, useSelector } from 'react-redux'

//import { initialState } from '../store/configureStore';
import { fetchAuth } from '../actions/authActions'

import {
  fetchMyFollowers
  } from '../actions/myFollowersSearchActions'
  
import {
  fetchSentMessages
  } from '../actions/sentMessagesSearchActions'
  
import {
  fetchReceivedMessages
  } from '../actions/receivedMessagesSearchActions'

import {
  fetchRecentCommentersSearches
  } from '../actions/commentersSearchActions'

import {
  fetchRecentFollowersSearches
  } from '../actions/followersSearchActions'
  

export function handleLoginChange(event, context) {
  
        const { name, value } = event.target
        
        if (name === 'scUsername') {
            context.dispatch({
                type: "LOGIN_USERNAME_CHANGE",
                scUsername: value
            })
        } else  if (name === 'scPassword') {
            context.dispatch({
                type: "LOGIN_PASSWORD_CHANGE",
                scPassword: value
            })
        }
        
        if(context.state.scUsername && context.state.scUsername.length > 0 && context.state.scPassword && context.state.scPassword.length > 0) {
            context.dispatch({
                type: "LOGIN_SUBMIT_ENABLE"
          })
        } else {
            context.dispatch({
                type: "LOGIN_SUBMIT_DISABLE"
          })
        }

    
}



export function handleLoginSubmit(event, context) {
  

        context.dispatch({type: "LOGIN_SUBMITTED"});
        
        axios({
            method: 'post',
            url: 'https://scbm.amfdev.co.uk/api/login/',
            headers: {}, 
            data: {
              scUsername: context.state.scUsername,
              scPassword: context.state.scPassword
            }
            })
            .then(json => catchLoginUserNotFoundError(json.data, context.dispatch))
            .then(json => catchLoginCookieError(json, context.dispatch))
            .then(json => doLoginSuccess(json, context.dispatch))
            .then(json => context.dispatch(fetchReceivedMessages()))
            .then(json => context.dispatch(fetchSentMessages()))
            .then(json => context.dispatch(fetchMyFollowers()))
            .then(json => context.dispatch(fetchRecentCommentersSearches()))
            .then(json => context.dispatch(fetchRecentFollowersSearches()))
             .catch(error => {

                if (error.response) {   
                      context.dispatch({
                          type: "LOGIN_UNKNOWN_ERROR"
                      })  
                }
              });
                  
    
}


export function handleLoginSwitchToSignup(dispatch) {
       
        dispatch({
                type: "LOGIN_SWITCH_TO_SIGNUP"
        })
        
}
  
  
function catchLoginUserNotFoundError(json, dispatch) {
    //console.log('catchLoginUserNotFound')
    if (!json.userFound) {
        dispatch({
                type: "LOGIN_USER_NOT_FOUND_ERROR"
              })
        throw Error(json.loginError);
    }
    
  return json;
}


function catchLoginCookieError(json, dispatch) {
    //console.log('catchLoginCookieError')
    if (!json.scCookiesValid) {
        dispatch({
                type: "LOGIN_COOKIE_ERROR"
              })
        throw Error(json.loginError);
    }
    
  return json;
}


function doLoginSuccess(json, dispatch) {
    //console.log('doLoginSuccess')
 
        dispatch({
                type: "LOGIN_SUCCESS",
                userData: json.userData,
                userSettings: JSON.parse(json.userData.userSettings)
              })
  return json;
}


export function handleLogoutSubmit(context) {
    
    console.log('logout')

        axios({
            method: 'get',
            url: 'https://scbm.amfdev.co.uk/api/logout/'
            })
            .then(json => doLogout(json.data, context.dispatch))
            .then(json => context.dispatch(fetchAuth(context.dispatch)))
             .catch(error => console.log(error));   
    
}


function doLogout(json, dispatch) {
  
    if (json.logoutSuccess) {
        dispatch({
                type: "LOGOUT_SUCCESS",
                //initialState: initialState
              })
    } else {
        throw Error("Logout error");
    }
    
  return json;
}
